/// What a picker's filter narrows to.
enum FileKind { any, custom, image, video, media }

/// The picker filter an HTML `accept` list narrows to.
class FileFilter {
  const FileFilter(this.type, this.extensions);

  /// Reads [accept], the list a web target passes to its file input: file
  /// extensions (`.pdf`), MIME types and `type/*` wildcards, comma
  /// separated; `null` or empty accepts any file. Only extensions, or only
  /// the image and video wildcards, narrow the picker; any other list opens
  /// it unfiltered, as a browser's file dialog lets the user choose any file
  /// too. The server enforces the upload's own constraints either way.
  factory FileFilter.parse(String? accept) {
    final entries = [
      for (final entry in (accept ?? '').split(','))
        if (entry.trim().isNotEmpty) entry.trim().toLowerCase(),
    ];
    if (entries.isEmpty) {
      return const FileFilter(FileKind.any, null);
    }
    if (entries.every((entry) => entry.startsWith('.') && entry.length > 1)) {
      return FileFilter(FileKind.custom, [for (final entry in entries) entry.substring(1)]);
    }
    final kinds = entries.toSet();
    if (kinds.difference(const {'image/*'}).isEmpty) {
      return const FileFilter(FileKind.image, null);
    }
    if (kinds.difference(const {'video/*'}).isEmpty) {
      return const FileFilter(FileKind.video, null);
    }
    if (kinds.difference(const {'image/*', 'video/*'}).isEmpty) {
      return const FileFilter(FileKind.media, null);
    }
    return const FileFilter(FileKind.any, null);
  }

  final FileKind type;
  final List<String>? extensions;
}

